devices.targetScript:
# STM32F100C4：先检查硅片组与标称 Flash 容量，再允许下载。
source [find target/stm32f1x.cfg]
$_TARGETNAME configure -event reset-init {}
$_TARGETNAME configure -event reset-start {}
proc studiox_check_target {} {
    set id [expr {[lindex [read_memory 0xe0042000 32 1] 0] & 0xfff}]
    set kb [lindex [read_memory 0x1ffff7e0 16 1] 0]
    if {$id != 0x420 || $kb != 16} {
        error "Expected STM32F100C4 (device ID 0x420, 16 KiB Flash); got ID $id, $kb KiB"
    }
}

