$_TARGETNAME configure -event reset-start {}
proc studiox_check_target {} {
    set id [expr {[lindex [read_memory 0xe0042000 32 1] 0] & 0xfff}]
    set kb [lindex [read_memory 0x1fff7a22 16 1] 0]
    if {$id != 0x463 || $kb != 1536} {
        error "Expected STM32F423MH (device ID 0x463, 1536 KiB Flash); got ID $id, $kb KiB"
    }
}

